from collections import defaultdict
from typing import Dict, List, Optional, Tuple

from sqlalchemy import select, func
from sqlalchemy.orm import Session

from packages.domain.analytics.analytics_query import AnalyticsQuery
from packages.domain.analytics.analytics_reader import AnalyticsReader
from packages.domain.analytics.character_activity_metric import CharacterActivityMetric
from packages.domain.analytics.event_distribution_metric import EventDistributionMetric
from packages.domain.analytics.event_statistics import EventStatistics
from packages.domain.analytics.relationship_metric import (
    RelationshipAnalytics,
    RelationshipChapterDelta,
    RelationshipMetric,
)
from infrastructure.database.models.event import EventModel
from infrastructure.database.models.chapter import ChapterModel
from infrastructure.database.models.canonical_relationship import CanonicalRelationshipModel


def _buckets(counts: Dict[str, int], *, by_key_asc: bool = False) -> Tuple[EventDistributionMetric, ...]:
    """Deterministic bucket ordering (R3): count DESC, key ASC — or key ASC when
    the axis is inherently ordered (chapter numbers, sequence positions)."""
    ordered = sorted(counts.items(), key=lambda kv: kv[0] if by_key_asc else (-kv[1], kv[0]))
    return tuple(EventDistributionMetric(key=k, count=v) for k, v in ordered)


class SQLAlchemyAnalyticsReader(AnalyticsReader):
    """Read-only analytics over canonical tables. Never mutates (R1)."""

    def __init__(self, session: Session):
        self.session = session

    # ------------------------------------------------------------------
    # Shared scoped-event filter. All chapter scoping goes through the
    # ChapterModel join (same as SQLAlchemyCanonicalEventReader).
    # ------------------------------------------------------------------
    def _scoped_event_columns(self, query: AnalyticsQuery):
        stmt = select(
            EventModel,
            ChapterModel.number.label("chapter_number"),
        ).join(ChapterModel, EventModel.chapter_id == ChapterModel.id)

        conditions = [EventModel.series_id == query.series_id]
        if query.from_chapter is not None:
            conditions.append(ChapterModel.number >= query.from_chapter)
        if query.to_chapter is not None:
            conditions.append(ChapterModel.number <= query.to_chapter)
        return stmt.where(*conditions)

    def _series_exists(self, series_id: str) -> bool:
        from infrastructure.database.models.series import SeriesModel
        stmt = select(func.count()).select_from(SeriesModel).where(SeriesModel.id == series_id)
        return bool(self.session.execute(stmt).scalar())

    # ------------------------------------------------------------------
    # M3.0.2 — Event Statistics
    # ------------------------------------------------------------------
    def get_event_statistics(self, query: AnalyticsQuery) -> EventStatistics:
        base = self._scoped_event_columns(query).subquery()
        event_cols = (base.c.type, base.c.subject_id, base.c.target_id,
                      base.c.chapter_number, base.c.sequence)

        total_events = self.session.execute(
            select(func.count()).select_from(base)
        ).scalar() or 0

        distinct_chapters = self.session.execute(
            select(func.count(func.distinct(base.c.chapter_number))).select_from(base)
        ).scalar() or 0

        events_by_chapter: Dict[str, int] = {}
        for row in self.session.execute(
            select(base.c.chapter_number, func.count()).group_by(base.c.chapter_number)
        ):
            events_by_chapter[str(row[0])] = row[1]

        events_by_type: Dict[str, int] = {}
        for row in self.session.execute(
            select(event_cols[0], func.count()).select_from(base).group_by(event_cols[0])
        ):
            events_by_type[row[0]] = row[1]

        events_by_sequence: Dict[str, int] = {}
        for row in self.session.execute(
            select(event_cols[4], func.count()).select_from(base).group_by(event_cols[4])
        ):
            events_by_sequence[str(row[0])] = row[1]

        events_by_entity: Dict[str, int] = defaultdict(int)
        for row in self.session.execute(
            select(event_cols[1], func.count()).select_from(base).group_by(event_cols[1])
        ):
            events_by_entity[str(row[0])] += row[1]
        for row in self.session.execute(
            select(event_cols[2], func.count())
            .select_from(base)
            .where(event_cols[2].isnot(None))
            .group_by(event_cols[2])
        ):
            events_by_entity[str(row[0])] += row[1]

        return EventStatistics(
            total_events=total_events,
            chapters=distinct_chapters,
            events_by_chapter=_buckets(events_by_chapter, by_key_asc=True),
            events_by_type=_buckets(events_by_type),
            events_by_sequence=_buckets(events_by_sequence, by_key_asc=True),
            events_by_entity=_buckets(dict(events_by_entity)),
        )

    # ------------------------------------------------------------------
    # M3.0.3 — Entity Activity
    # ------------------------------------------------------------------
    def get_entity_activity(
        self,
        query: AnalyticsQuery,
        entity_id: Optional[str] = None,
    ) -> List[CharacterActivityMetric]:
        base = self._scoped_event_columns(query).subquery()

        subject_rows = self.session.execute(
            select(base.c.subject_id,
                   func.count(),
                   func.count(func.distinct(base.c.chapter_number)),
                   func.min(base.c.chapter_number),
                   func.max(base.c.chapter_number))
            .select_from(base)
            .group_by(base.c.subject_id)
        ).all()
        target_rows = self.session.execute(
            select(base.c.target_id,
                   func.count(),
                   func.count(func.distinct(base.c.chapter_number)),
                   func.min(base.c.chapter_number),
                   func.max(base.c.chapter_number))
            .select_from(base)
            .where(base.c.target_id.isnot(None))
            .group_by(base.c.target_id)
        ).all()

        # entity_id -> accumulated per-side stats
        stats: Dict[str, dict] = {}

        def _acc(entity: str, side: str, count: int, chapters: int, first: int, last: int):
            s = stats.setdefault(entity, {
                "subject_count": 0, "target_count": 0,
                "chapters": set(), "first": None, "last": None,
            })
            s[f"{side}_count"] += count
            s["chapters"].add(chapters)  # per-group distinct-chapter counts; unioned below
            s["_chapter_counts"] = s.get("_chapter_counts", []) + [(entity, chapters)]
            s["first"] = min(s["first"], first) if s["first"] is not None else first
            s["last"] = max(s["last"], last) if s["last"] is not None else last

        for sid, cnt, chs, first, last in subject_rows:
            _acc(str(sid), "subject", cnt, chs, first, last)
        for tid, cnt, chs, first, last in target_rows:
            _acc(str(tid), "target", cnt, chs, first, last)

        # chapters_present needs a true union of chapters across sides;
        # re-query grouped by (entity-side union) via a UNION ALL.
        union_rows = self.session.execute(
            select(func.union_all(
                select(base.c.subject_id.label("eid"), base.c.chapter_number),
                select(base.c.target_id.label("eid"), base.c.chapter_number)
            ))
        )

