            str(row[0]): row[1:]
            for row in self.session.execute(
                select(
                    both_sides.c.eid,
                    func.count().label("event_count"),
                    func.count(func.distinct(both_sides.c.chapter_number)).label("chapters_present"),
                    func.min(both_sides.c.chapter_number).label("first_seen"),
                    func.max(both_sides.c.chapter_number).label("last_seen"),
                ).group_by(both_sides.c.eid)
            )
        }

        subject_counts = {
            str(row[0]): row[1]
            for row in self.session.execute(
                select(base.c.subject_id, func.count()).select_from(base).group_by(base.c.subject_id)
            )
        }
        target_counts = {
            str(row[0]): row[1]
            for row in self.session.execute(
                select(base.c.target_id, func.count())
                .select_from(base)
                .where(base.c.target_id.isnot(None))
                .group_by(base.c.target_id)
            )
        }

