  CharacterActivityDTO,
  RelationshipAnalyticsDTO,
} from '../types';

export interface AnalyticsScope {
  from?: number;
  to?: number;
}

const scopeParams = (scope: AnalyticsScope): string => {
  const params = new URLSearchParams();
  if (scope.from != null) params.set('from', String(scope.from));
  if (scope.to != null) params.set('to', String(scope.to));
  const qs = params.toString();
  return qs ? `?${qs}` : '';
};

export const analyticsApi = {
  getOverview: (seriesId: string, scope: AnalyticsScope = {}): Promise<AnalyticsOverviewDTO> =>
    apiClient<AnalyticsOverviewDTO>(`/series/${seriesId}/analytics/overview${scopeParams(scope)}`),

  getEntityActivity: (
    seriesId: string,
    entityId: string,
    scope: AnalyticsScope = {},
    limit: number = 50,
  ): Promise<CharacterActivityDTO[]> =>
    apiClient<CharacterActivityDTO[]>(
      `/series/${seriesId}/analytics/entities/${encodeURIComponent(entityId)}${scopeParams(scope)}&limit=${limit}`.replace('?&', '?'),
    ),

  getRelationships: (
    seriesId: string,
    scope: AnalyticsScope = {},
    limit: number = 50,
  ): Promise<RelationshipAnalyticsDTO> =>
    apiClient<RelationshipAnalyticsDTO>(
      `/series/${seriesId}/analytics/relationships${scopeParams(scope)}${scope.from != null || scope.to != null ? '&' : '?'}limit=${limit}`,
    ),
};

