foreach ($p in @("$env:ProgramFiles\PostgreSQL\18\bin", "C:\PostgreSQL\18\bin", "$env:LOCALAPPDATA\Programs\PostgreSQL", "$env:USERPROFILE\scoop\apps\postgresql", "C:\tools\postgresql")) { if (Test-Path $p) { "FOUND: $p" } }
# Also check chocolatey / winget style installs and ProgramDirs
foreach ($p in @("C:\Program Files\PostgreSQL", "D:\PostgreSQL")) { if (Test-Path $p) { Get-ChildItem $p -Directory | ForEach-Object { $_.FullName; Get-ChildItem $_.FullName -Directory | Select-Object -ExpandProperty Name } } }
# Registry: installer records
Get-ItemProperty "HKLM:\SOFTWARE\PostgreSQL*" -ErrorAction SilentlyContinue | Format-List

# Broad but bounded search for postgres.exe on likely drives
$found = @()
foreach ($root in @("C:\Program Files", "C:\Program Files (x86)", "D:\", "E:\")) {
  if (Test-Path $root) {
    $found += Get-ChildItem $root -Recurse -Depth 3 -Filter "postgres.exe" -ErrorAction SilentlyContinue | Select-Object -First 3 -ExpandProperty FullName
  }
}
if ($found) { $found } else { "postgres.exe not found in shallow scan of C:/Program Files*, D:\, E:\" }

# The binaries are gone but data dir remains. Check E-drive Lore Time folder and user dirs for a portable PG
foreach ($p in @("E:\Lore Time", "$env:USERPROFILE\Downloads", "$env:USERPROFILE\Desktop")) {
  if (Test-Path $p) {
    Get-ChildItem $p -Directory -ErrorAction SilentlyContinue | Where-Object Name -imatch "postgres|pgsql|pg" | Select-Object -ExpandProperty FullName
  }
}
# winget availability for a clean install path
